/// <summary>
/// PricingAttribute of table <c>CustTable</c> field Memo.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustTableMemo extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, Memo);
}

    public Set getAllowedValues()
    {
        var         ret = new Set(Types::String);
        CustTable   custTable;

        while select Memo from custTable
        {
            ret.add(custTable.Memo);
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(CustTable, Memo));
        qbr.value(queryValue(_value));
    }
